23:     public static int Status(Outcome outcome)=>outcome switch { Outcome.Saved=>200,Outcome.NoChange=>200,Outcome.ValidationFailed=>422,Outcome.Forbidden=>403,Outcome.NotFound=>404,Outcome.Conflict or Outcome.ConfirmationRequired=>409,_=>503 };
24:     private static (string Id,string Message) SaveMessage(Outcome outcome)=>outcome switch {
